import { anthropic } from "@ai-sdk/anthropic";
import { streamText, type ModelMessage, stepCountIs } from "ai";
import { SYSTEM_PROMPT } from "./prompt";
import { extractionToolset } from "./tools";

export function extractionAgent(messages: ModelMessage[]) {
  return streamText({
    model: anthropic("claude-sonnet-4-5-20250929"),
    system: SYSTEM_PROMPT,
    messages,
    tools: extractionToolset,
    stopWhen: [stepCountIs(25)],
  });
}

import { ToolSet } from "ai";
import { getDocumentMetadataTool } from "./get-document-metadata";
import { documentInformationExtractionTool } from "./document-information-extraction";
import { getSheetMetadataTool } from "./get-sheet-metadata";
import { spreadsheetInformationExtractionTool } from "./spreadsheet-information-extraction";
import { imageInformationExtractionTool } from "./image-information-extraction";
import { saveExtractionTool } from "./save-extraction";

export const extractionToolset = {
  get_document_metadata: getDocumentMetadataTool,
  document_information_extraction: documentInformationExtractionTool,
  get_sheet_metadata: getSheetMetadataTool,
  spreadsheet_information_extraction: spreadsheetInformationExtractionTool,
  image_information_extraction: imageInformationExtractionTool,
  save_extraction: saveExtractionTool,
} as ToolSet;

import { InferUITools, UIMessage } from "ai";
import { extractionToolset } from "./toolset";

type ExtractionTools = InferUITools<typeof extractionToolset>;

export type ExtractionUIMessage = UIMessage<never, never, ExtractionTools>;

import * as fs from "fs";
import * as path from "path";

export const EXTRACTION_AGENT_BASE_DIR = path.join(
  process.cwd(),
  "data",
  "extraction-agent.local"
);

const IMAGE_MIME_BY_EXT: Record<string, string> = {
  ".png": "image/png",
  ".jpg": "image/jpeg",
  ".jpeg": "image/jpeg",
  ".webp": "image/webp",
  ".gif": "image/gif",
};

function ensureDir(dirPath: string) {
  if (!fs.existsSync(dirPath)) {
    fs.mkdirSync(dirPath, { recursive: true });
  }
}

function safeFileName(input: string) {
  return input.toLowerCase().replace(/[^a-z0-9-_]+/g, "-");
}

/** Resolve a user path inside the extraction workspace; reject traversal. */
export function resolveWorkspacePath(filePath: string) {
  ensureDir(EXTRACTION_AGENT_BASE_DIR);
  const base = path.resolve(EXTRACTION_AGENT_BASE_DIR);
  const fullPath = path.resolve(base, filePath);
  if (!fullPath.startsWith(base + path.sep) && fullPath !== base) {
    throw new Error(
      `Access denied: path "${filePath}" is outside the extraction workspace.`
    );
  }
  return fullPath;
}

export function readWorkspaceFile(filePath: string) {
  const fullPath = resolveWorkspacePath(filePath);
  if (!fs.existsSync(fullPath)) {
    throw new Error(`File not found: ${filePath}`);
  }
  return fs.readFileSync(fullPath);
}

export function writeWorkspaceFile(
  filePath: string,
  contents: string | Buffer
) {
  const fullPath = resolveWorkspacePath(filePath);
  ensureDir(path.dirname(fullPath));
  fs.writeFileSync(fullPath, contents);
  return path.relative(EXTRACTION_AGENT_BASE_DIR, fullPath);
}

export function getImageMediaType(filePath: string) {
  const ext = path.extname(filePath).toLowerCase();
  const mediaType = IMAGE_MIME_BY_EXT[ext];
  if (!mediaType) {
    throw new Error(
      `Unsupported image type "${ext}". Use png, jpg, jpeg, webp, or gif.`
    );
  }
  return mediaType;
}

export function saveArtifact(folder: string, fileName: string, payload: unknown) {
  const relative = path.join(folder, fileName);
  const body =
    typeof payload === "string" ? payload : JSON.stringify(payload, null, 2);
  return writeWorkspaceFile(relative, body);
}

export function buildTaskMetadata(taskName: string) {
  return {
    task_name: safeFileName(taskName),
    created_at: new Date().toISOString(),
  };
}

export async function extractPdfPages(
  sourcePdfDoc: import("pdf-lib").PDFDocument,
  startPage: number,
  endPage: number
) {
  const { PDFDocument } = await import("pdf-lib");
  if (
    typeof startPage !== "number" ||
    typeof endPage !== "number" ||
    startPage <= 0 ||
    endPage < startPage
  ) {
    throw new Error(
      "Invalid page range. Start must be <= end, and both must be positive."
    );
  }

  const totalPages = sourcePdfDoc.getPageCount();
  if (startPage > totalPages || endPage > totalPages) {
    throw new Error(
      `Invalid page range: the document only has ${totalPages} pages.`
    );
  }

  const newPdfDoc = await PDFDocument.create();
  const startIndex = startPage - 1;
  const pageIndices = Array.from(
    { length: endPage - startIndex },
    (_, i) => startIndex + i
  );
  const copiedPages = await newPdfDoc.copyPages(sourcePdfDoc, pageIndices);
  copiedPages.forEach((page) => newPdfDoc.addPage(page));
  return newPdfDoc;
}

import { tool } from "ai";
import { PDFDocument } from "pdf-lib";
import { readWorkspaceFile } from "./core";
import { getDocumentMetadataSchema } from "./schema";

async function tryOrNull<T>(fn: () => Promise<T>): Promise<T | null> {
  try {
    return await fn();
  } catch {
    return null;
  }
}

export const getDocumentMetadataTool = tool({
  description:
    "Get metadata for a PDF (page count, title, author, creator, subject).",
  inputSchema: getDocumentMetadataSchema,
  execute: async ({ file_path }) => {
    if (!file_path.toLowerCase().endsWith(".pdf")) {
      throw new Error("Only PDF files are supported for document metadata.");
    }

    const buffer = readWorkspaceFile(file_path);
    const document = await PDFDocument.load(buffer);

    return {
      success: true,
      content: {
        page_count: document.getPageCount(),
        title: await tryOrNull(async () => document.getTitle()),
        author: await tryOrNull(async () => document.getAuthor()),
        creator: await tryOrNull(async () => document.getCreator()),
        producer: await tryOrNull(async () => document.getProducer()),
        subject: await tryOrNull(async () => document.getSubject()),
        keywords: await tryOrNull(async () => document.getKeywords()),
        creationDate: (
          await tryOrNull(async () => document.getCreationDate())
        )?.toISOString(),
      },
    };
  },
});

import { anthropic } from "@ai-sdk/anthropic";
import { generateText, tool } from "ai";
import { PDFDocument } from "pdf-lib";
import { extractPdfPages, readWorkspaceFile } from "./core";
import { documentInformationExtractionSchema } from "./schema";

export const documentInformationExtractionTool = tool({
  description:
    "Extract information from a PDF with optional page range and citations.",
  inputSchema: documentInformationExtractionSchema,
  execute: async ({
    file_path,
    instructions,
    include_citations,
    page_range,
  }) => {
    if (!file_path.toLowerCase().endsWith(".pdf")) {
      throw new Error("Only PDF files are supported for document extraction.");
    }

    const buffer = readWorkspaceFile(file_path);
    const document = await PDFDocument.load(buffer);
    const totalPages = document.getPageCount();

    if (page_range?.end && !page_range.start) {
      throw new Error("Start page is required when end page is provided.");
    }

    const finalDocument = page_range?.start
      ? await extractPdfPages(
          document,
          page_range.start,
          page_range.end ?? totalPages
        )
      : document;

    const documentBuffer = Buffer.from(await finalDocument.save());

    const { text } = await generateText({
      model: anthropic("claude-sonnet-4-5-20250929"),
      maxOutputTokens: 8192,
      system: include_citations
        ? "You extract information from PDF documents. For every claim, include a citation with page number and an exact snippet from the document when possible."
        : "You extract information from PDF documents according to the user's instructions.",
      messages: [
        {
          role: "user",
          content: [
            { type: "text", text: instructions },
            {
              type: "file",
              data: documentBuffer,
              mediaType: "application/pdf",
            },
          ],
        },
      ],
    });

    return {
      success: true,
      content: {
        file_path,
        result: text,
      },
    };
  },
});

import { tool } from "ai";
import * as XLSX from "xlsx";
import { readWorkspaceFile } from "./core";
import { getSheetMetadataSchema } from "./schema";

export const getSheetMetadataTool = tool({
  description:
    "Get metadata for a spreadsheet (sheet names, dimensions, formulas, filters).",
  inputSchema: getSheetMetadataSchema,
  execute: async ({ file_path }) => {
    const lower = file_path.toLowerCase();
    if (
      !lower.endsWith(".xlsx") &&
      !lower.endsWith(".xls") &&
      !lower.endsWith(".csv")
    ) {
      throw new Error("File must be .xlsx, .xls, or .csv.");
    }

    const buffer = readWorkspaceFile(file_path);
    const fileFormat = lower.endsWith(".csv")
      ? "csv"
      : lower.endsWith(".xls")
        ? "xls"
        : "xlsx";

    const workbook = XLSX.read(buffer, {
      type: "buffer",
      cellFormula: true,
      cellStyles: true,
      sheetStubs: true,
    });

    const sheets = workbook.SheetNames.map((sheetName) => {
      const worksheet = workbook.Sheets[sheetName]!;
      const range = XLSX.utils.decode_range(worksheet["!ref"] || "A1");
      const rows = range.e.r - range.s.r + 1;
      const columns = range.e.c - range.s.c + 1;

      let isTabular = false;
      if (rows > 1 && columns > 1) {
        const firstRowCells: string[] = [];
        for (let c = range.s.c; c <= range.e.c; c++) {
          const cellAddress = XLSX.utils.encode_cell({ r: range.s.r, c });
          const cell = worksheet[cellAddress];
          if (cell?.v) firstRowCells.push(String(cell.v));
        }
        isTabular = firstRowCells.length >= columns * 0.7;
      }

      let hasFormulas = false;
      let referencesOtherSheets = false;
      const hasFilters = Boolean(worksheet["!autofilter"]);

      Object.keys(worksheet).forEach((cellAddress) => {
        if (cellAddress[0] === "!") return;
        const cell = worksheet[cellAddress];
        if (cell?.f) {
          hasFormulas = true;
          if (cell.f.includes("!") || cell.f.includes("[")) {
            referencesOtherSheets = true;
          }
        }
      });

      return {
        name: sheetName,
        rows,
        columns,
        is_tabular: isTabular,
        has_formulas: hasFormulas,
        has_filters: hasFilters,
        references_other_sheets: referencesOtherSheets,
      };
    });

    return {
      success: true,
      content: {
        sheets,
        total_sheets: workbook.SheetNames.length,
        file_format: fileFormat,
      },
    };
  },
});

import { anthropic } from "@ai-sdk/anthropic";
import { generateText, tool } from "ai";
import * as XLSX from "xlsx";
import { readWorkspaceFile } from "./core";
import { spreadsheetInformationExtractionSchema } from "./schema";

const LARGE_SHEET_CELL_THRESHOLD = 4000;

export const spreadsheetInformationExtractionTool = tool({
  description:
    "Extract information from an xlsx, xls, or csv spreadsheet with cell citations.",
  inputSchema: spreadsheetInformationExtractionSchema,
  execute: async ({
    file_path,
    instructions,
    include_citations,
    sheet_names,
    cell_range,
  }) => {
    const lower = file_path.toLowerCase();
    if (
      !lower.endsWith(".xlsx") &&
      !lower.endsWith(".xls") &&
      !lower.endsWith(".csv")
    ) {
      throw new Error("File must be .xlsx, .xls, or .csv.");
    }

    const buffer = readWorkspaceFile(file_path);
    const workbook = XLSX.read(buffer, {
      type: "buffer",
      cellFormula: true,
      cellStyles: true,
      sheetStubs: true,
    });

    const sheetsToAnalyze = sheet_names?.length
      ? sheet_names
      : workbook.SheetNames;

    let totalCells = 0;
    const sheetSizes: {
      name: string;
      rows: number;
      columns: number;
      cells: number;
    }[] = [];

    for (const sheetName of sheetsToAnalyze) {
      const worksheet = workbook.Sheets[sheetName];
      if (!worksheet) continue;

      const range = XLSX.utils.decode_range(worksheet["!ref"] || "A1");
      let rows = range.e.r - range.s.r + 1;
      let columns = range.e.c - range.s.c + 1;

      if (cell_range) {
        try {
          const customRange = XLSX.utils.decode_range(cell_range);
          rows = customRange.e.r - customRange.s.r + 1;
          columns = customRange.e.c - customRange.s.c + 1;
        } catch {
          // keep full sheet size
        }
      }

      const cells = rows * columns;
      totalCells += cells;
      sheetSizes.push({ name: sheetName, rows, columns, cells });
    }

    if (totalCells > LARGE_SHEET_CELL_THRESHOLD) {
      return {
        success: false,
        content: {
          analysis_method: "range_required" as const,
          result: `Spreadsheet is too large for a single pass (${totalCells.toLocaleString()} cells; limit ${LARGE_SHEET_CELL_THRESHOLD.toLocaleString()}).

Sheet sizes:
${sheetSizes
  .map(
    (s) =>
      `- ${s.name}: ${s.rows} rows × ${s.columns} columns (${s.cells.toLocaleString()} cells)`
  )
  .join("\n")}

Call this tool again with sheet_names and/or a smaller cell_range (e.g. A1:F100).`,
        },
      };
    }

    const sheetsData: { name: string; data: string }[] = [];
    for (const sheetName of sheetsToAnalyze) {
      const worksheet = workbook.Sheets[sheetName];
      if (!worksheet) continue;

      const csvData = XLSX.utils.sheet_to_csv(worksheet, {
        ...(cell_range ? { range: cell_range } : {}),
        forceQuotes: true,
      });

      sheetsData.push({ name: sheetName, data: csvData });
    }

    let systemPrompt =
      "You extract information from spreadsheet data provided as CSV. Follow the user's instructions carefully.";
    if (include_citations) {
      systemPrompt +=
        " For every claim, cite sheet name and cell reference (e.g. Sheet1!A5) with the exact cell value when possible.";
    }

    let dataContent = "Spreadsheet data:\n\n";
    for (const sheet of sheetsData) {
      dataContent += `=== Sheet: ${sheet.name} ===\n${sheet.data}\n\n`;
    }

    const { text } = await generateText({
      model: anthropic("claude-sonnet-4-5-20250929"),
      maxOutputTokens: 8192,
      system: systemPrompt,
      messages: [
        {
          role: "user",
          content: [
            { type: "text", text: instructions },
            { type: "text", text: dataContent },
          ],
        },
      ],
    });

    return {
      success: true,
      content: {
        file_path,
        analysis_method: "direct" as const,
        result: text,
      },
    };
  },
});

import { anthropic } from "@ai-sdk/anthropic";
import { generateText, tool } from "ai";
import { getImageMediaType, readWorkspaceFile } from "./core";
import { imageInformationExtractionSchema } from "./schema";

export const imageInformationExtractionTool = tool({
  description:
    "Extract text and facts from an image (png, jpg, jpeg, webp, gif).",
  inputSchema: imageInformationExtractionSchema,
  execute: async ({ file_path, instructions, include_citations }) => {
    const mediaType = getImageMediaType(file_path);
    const image = readWorkspaceFile(file_path);

    const { text } = await generateText({
      model: anthropic("claude-sonnet-4-5-20250929"),
      maxOutputTokens: 4096,
      system: include_citations
        ? `You extract information from images. Cite the source file path (${file_path}) when stating extracted facts.`
        : "You extract information from images according to the user's instructions.",
      messages: [
        {
          role: "user",
          content: [
            { type: "text", text: instructions },
            { type: "image", image, mediaType },
          ],
        },
      ],
    });

    return {
      success: true,
      content: {
        file_path,
        result: text,
      },
    };
  },
});

import { tool } from "ai";
import { buildTaskMetadata, writeWorkspaceFile } from "./core";
import { saveExtractionSchema } from "./schema";

export const saveExtractionTool = tool({
  description:
    "Save extraction results as markdown or JSON under data/extraction-agent.local.",
  inputSchema: saveExtractionSchema,
  execute: async ({ task_name, format, content }) => {
    const meta = buildTaskMetadata(task_name);
    const extension = format === "json" ? "json" : "md";
    const relativePath = `${meta.task_name}/${meta.task_name}.${extension}`;

    if (format === "json") {
      try {
        JSON.parse(content);
      } catch {
        throw new Error("content must be valid JSON when format is json.");
      }
    }

    const savedPath = writeWorkspaceFile(relativePath, content);

    return {
      success: true,
      content: {
        path: savedPath,
        format,
        task_name: meta.task_name,
        created_at: meta.created_at,
      },
    };
  },
});
